+func TestDiagnosticTextContentShapes(t *testing.T) {
+	text := func(s string) any { return map[string]any{"type": "text", "text": s} }
+	cases := []struct {
+		name string
+		item any
+		want string
+	}{
+		{"string content", map[string]any{"content": "plain\ntext"}, "plain\ntext"},
+		{"single text block", map[string]any{"content": []any{text("a")}}, "a"},
+		{"multiple text blocks", map[string]any{"content": []any{text("a"), text("b"), text("c")}}, "a\nb\nc"},
+		{"non-map blocks", map[string]any{"content": []any{"x", 1, nil, []any{"y"}}}, ""},
+		{"map without text", map[string]any{"content": []any{map[string]any{"type": "image"}}}, ""},
+		{"map with non-string text", map[string]any{"content": []any{map[string]any{"type": "text", "text": 7}}}, ""},
+		{"malformed between text blocks", map[string]any{"content": []any{text("a"), "x", map[string]any{"text": 7}, text("b")}}, "a\nb"},
+		{"unsupported number content", map[string]any{"content": 7}, ""},
+		{"unsupported string list content", map[string]any{"content": []string{"a"}}, ""},
+		{"unsupported map content", map[string]any{"content": map[string]any{"text": "a"}}, ""},
+		{"unsupported missing content", map[string]any{}, ""},
+		{"unsupported non-map item", "x", ""},
+	}
+	for _, tc := range cases {
+		if got := DiagnosticText(tc.item); got != tc.want {
+			t.Errorf("%s: DiagnosticText = %q, want %q", tc.name, got, tc.want)
+		}
+	}
+}
+
+func TestMaterialText(t *testing.T) {
+	cases := []struct {
+		name  string
+		block any
+		want  string
+		ok    bool
+	}{
+		{"text block", map[string]any{"text": "a"}, "a", true},
+		{"non-map block", "x", "", false},
+		{"map without text", map[string]any{}, "", false},
+		{"map with non-string text", map[string]any{"text": 7}, "", false},
+	}
+	for _, tc := range cases {
+		got, ok := MaterialText(tc.block)
+		if got != tc.want || ok != tc.ok {
+			t.Errorf("%s: MaterialText = %q, %v, want %q, %v", tc.name, got, ok, tc.want, tc.ok)
+		}
+	}
+}
